function localDate(offset = 0) { const date = new Date(); date.setHours(12, 0, 0, 0); date.setDate(date.getDate() + offset); return date.toISOString().slice(0, 10); }
function displayDate(value) { try { return new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "2-digit", year: "numeric" }).format(new Date(`${value}T12:00:00`)); } catch { return value; } }
function dateShortcut(label, offset) { const value = localDate(offset); return `<button class="date-shortcut ${ui.date === value ? "active" : ""}" data-action="set-dispatch-date" data-date="${value}"><b>${label}</b><small>${displayDate(value)}</small></button>`; }
function layout(content) { const locked = planLock(); return `<header class="topbar"><div><p class="eyebrow">DISPATCH PILOT</p><h1>${esc(state.companyName || "My Transport Dispatch")}</h1></div><div class="header-actions"><span id="save-status">Saved on phone</span><button class="icon-button" data-action="go-settings">Settings</button></div></header><main><section class="date-strip"><label>Dispatch / log date<input id="dispatch-date" type="date" value="${esc(ui.date)}"></label><div class="date-shortcuts">${dateShortcut("Yesterday", -1)}${dateShortcut("Today", 0)}${dateShortcut("Tomorrow", 1)}${dateShortcut("Day after", 2)}</div><span class="${locked ? "plan-lock-indicator" : ""}">${locked ? `Plan locked · ${esc(planLockTime(locked))}` : activeAssignments().length ? `${activeAssignments().length} trips planned` : "Plan not generated"}</span></section>${content}</main><nav class="bottom-nav daily-nav">${DAILY_TABS.map(([id, label]) => `<button class="${ui.tab === id ? "active" : ""}" data-tab="${id}"><b>${label.slice(0, 1)}</b><span>${label}</span></button>`).join("")}</nav>${ui.toast ? `<div class="toast ${esc(ui.toastTone)}">${esc(ui.toast)}</div>` : ""}`; }

function capabilityEditor(item) {
  const profiles = item.capabilities || [];
  return `<details class="capability-editor" ${ui.openTruck === item.id ? "open" : ""}><summary><b>Route plans</b><span>${esc(capabilitySummary(item))}</span></summary><p class="field-hint">Each line is one valid full-day route combination. For example: 5 Near, 3 Near + 1 Far, 4 Near + 1 Stone, or 3 Near + 1 Far + 1 Stone.</p><div class="capability-list">${profiles.map((profile) => `<div data-capability="${esc(profile.id)}"><span>Plan</span>${stepper("capability", `${item.id}|${profile.id}`, "near", profile.near)}<small>Near</small>${stepper("capability", `${item.id}|${profile.id}`, "far", profile.far)}<small>Far</small>${stepper("capability", `${item.id}|${profile.id}`, "stone", profile.stone)}<small>Stone</small><button class="delete" data-action="delete-capability" data-truck="${esc(item.id)}" data-capability="${esc(profile.id)}">Remove</button></div>`).join("")}</div><button class="secondary" data-action="add-capability" data-id="${esc(item.id)}">Add route plan</button></details>`;
}
function repairEditor(item) { const repair = item.repairCapacity || {}; return `<div class="repair-config"><b>Scheduled repair settings</b><div class="repair-grid"><label>Repair time<select data-repair-field="repairTime"><option ${item.repairTime === "Morning" ? "selected" : ""}>Morning</option><option ${item.repairTime === "Afternoon" ? "selected" : ""}>Afternoon</option></select></label><label class="inline-check"><input type="checkbox" data-repair-field="earlyRepair" ${item.earlyRepair ? "checked" : ""}> No early urgent jobs</label><label>Near${stepper("repair", item.id, "near", repair.near)}</label><label>Far${stepper("repair", item.id, "far", repair.far)}</label><label>Stone${stepper("repair", item.id, "stone", repair.stone)}</label></div><small>The repair capacity is used only while this truck is marked Scheduled Repair.</small></div>`; }
function trucksPage() {
  const totals = fleetTotals();
  return `<section class="page-title"><p class="eyebrow">STEP 1 — DAILY FLEET</p><h2>Availability and truck capability</h2><p>Changes save automatically. Maximum loads come from saved route combinations, not from a separate Daily number.</p></section><section class="mini-summary"><span><b>${dispatchableTrucks().length}</b> working trucks</span><span><b>${totals.Daily}</b> possible loads</span><span><b>${totals.Near}/${totals.Far}/${totals.Stone}</b> maximum N / F / S</span></section><section class="panel compact-panel"><div class="section-head"><div><h2>Tomorrow’s fleet</h2><small>Status, reason and maximum loads are under the frozen truck plate. Open Route plans only when a truck’s capability changes.</small></div></div><div class="table-scroll"><table class="compact-table fleet-table"><thead><tr><th class="sticky-col">Truck</th><th>Route plans and fairness</th></tr></thead><tbody>${state.trucks.map((item) => { const score = loadScore(state, item.id, ui.date); return `<tr data-truck="${esc(item.id)}" data-status="${esc(item.status.toLowerCase())}"><td class="sticky-col truck-cell"><b class="truck-name">${esc(truckLabel(item))}</b><select data-truck-field="status">${statusOptions(item.status)}</select><small><b>${maximumTruckTrips(item)}</b> maximum loads</small><label class="status-reason">Reason<input data-truck-field="statusReason" value="${esc(item.statusReason || "")}" placeholder="Off, breakdown, repair or quarry note"></label></td><td class="fleet-plan-cell">${capabilityEditor(item)}${repairEditor(item)}<small class="fairness-line"><b>30-day fairness</b> ${score.historical} loads · ${score.far} Far · ${score.stone} Stone · ${score.quarry} quarry · ${score.planned} planned</small></td></tr>`; }).join("")}</tbody></table></div></section><details class="panel compact-details add-under-list"><summary>Add truck</summary><form class="inline-form" data-form="new-truck"><input name="prefix" placeholder="Prefix"><input required name="number" placeholder="Full registration"><select name="status">${statusOptions("Available")}</select><input name="near" type="number" min="0" value="5" placeholder="Near"><input name="far" type="number" min="0" value="0" placeholder="Far"><input name="stone" type="number" min="0" value="0" placeholder="Stone"><button class="primary" type="submit">Add</button></form><small class="muted">This creates the first route plan. Add the truck’s other valid combinations from its row afterwards.</small></details>`;
}

function sequenceButtons(type, id) { return `<div class="sequence-actions"><button class="tiny-order" data-action="move-sequenced" data-list="${type}" data-id="${esc(id)}" data-direction="-1" aria-label="Move up">↑</button><button class="tiny-order" data-action="move-sequenced" data-list="${type}" data-id="${esc(id)}" data-direction="1" aria-label="Move down">↓</button></div>`; }
function orderRow(order) { return `<tr data-order="${esc(order.id)}"><td class="sticky-col"><b>${esc(customer(order.customerId)?.name || "Choose customer")}</b></td><td>${stepper("order", order.id, "loads", order.loads)}</td><td><select data-order-field="zone">${zoneOptions(order.zone)}</select></td><td><label class="inline-check"><input type="checkbox" data-order-field="early" ${order.early ? "checked" : ""}>Early</label></td><td><select data-order-field="materialId">${overrideOptions(order)}</select></td><td><input class="short-note" data-order-field="notes" value="${esc(order.notes)}" placeholder="Remark"></td><td>${sequenceButtons("orders", order.id)}</td><td><button class="delete" data-action="delete-order" data-id="${esc(order.id)}">×</button></td></tr>`; }
function ordersPage() { const totals = orderTotals(); const selected = customer(ui.newOrderCustomer); return `<section class="page-title"><p class="eyebrow">STEP 2 — CUSTOMER ORDER</p><h2>Reusable daily order template</h2><p>Yesterday’s order lines are copied automatically for a new date. Change the load with + / −; use Material override only for a special case.</p></section><section class="mini-summary"><span><b>${totals[0].count}</b> Near</span><span><b>${totals[1].count}</b> Far</span><span><b>${totals[2].count}</b> Stone</span><span><b>${totals.reduce((sum, item) => sum + item.count, 0)}</b> total</span></section><section class="panel compact-panel"><div class="section-head"><div><h2>Order lines</h2><small>Every edit is applied immediately to this phone.</small></div></div><div class="table-scroll"><table class="compact-table orders-table"><thead><tr><th class="sticky-col">Customer</th><th>Loads</th><th>Zone</th><th>Early</th><th>Material override only</th><th>Remark</th><th></th></tr></thead><tbody>${activeOrders().map(orderRow).join("") || "<tr><td colspan='7' class='empty-cell'>No orders for this date. Use the previous-date button below.</td></tr>"}</tbody></table></div></section><details class="panel compact-details"><summary>Add another customer order</summary><form class="add-order-form" data-form="new-order"><div class="inline-form"><select required name="customerId" data-new-order-customer>${customerOptions(ui.newOrderCustomer)}</select><input required name="loads" type="number" min="1" value="1"><select name="zone">${zoneOptions(selected?.defaultZone || "Near")}</select><label class="inline-check"><input name="early" type="checkbox">Early</label></div><div class="inline-form"><select name="materialId">${materialOptions("", selected?.id || "", selected?.kind || "")}</select><input name="notes" placeholder="Remark"><button class="primary" type="submit">Add line</button></div><small>Leave Material blank to use the customer’s saved material/source rule.</small></form></details>`; }

function tallyTable() { const tally = tallyForDate(state, ui.date); return `<section class="panel compact-panel tally-panel"><div class="section-head"><div><h2>Customer order vs planned trips</h2><small>Check again after a manual dispatch change.</small></div><span>${tally.every((item) => item.balance === 0) ? badge("Tally") : badge("Review")}</span></div><div class="table-scroll"><table class="compact-table tally-table"><thead><tr><th>Customer</th><th>Need</th><th>Planned</th><th>Balance</th></tr></thead><tbody>${tally.map((item) => `<tr class="${item.balance === 0 ? "ok" : "mismatch"}"><td>${esc(item.customerName)}</td><td>${item.required}</td><td>${item.planned}</td><td><b>${item.balance > 0 ? "+" : ""}${item.balance}</b></td></tr>`).join("") || "<tr><td colspan='4' class='empty-cell'>No order lines to check.</td></tr>"}</tbody></table></div></section>`; }
function tallyPage() { const capacity = fleetTotals(); const demand = Object.fromEntries(orderTotals().map((item) => [item.zone, item.count])); const dailyBalance = capacity.Daily - activeOrders().reduce((sum, item) => sum + number(item.loads), 0); const rows = ["Near", "Far", "Stone"].map((zone) => ({ zone, need: demand[zone], capacity: capacity[zone] })); const unresolved = state.lastAllocation?.date === ui.date ? state.lastAllocation.unresolved || [] : []; const permitWarnings = state.lastAllocation?.date === ui.date ? state.lastAllocation.permitWarnings || [] : []; const permit = sandpitPermitPlan(state, ui.date); const quarryRotation = permit.recommendedQuarryOnlyTruckIds.map((id) => truckLabel(truck(id))).join(" / "); const permitMessage = permit.groupCount ? `Sandpit permit plan: ${permit.groupCount} truck${permit.groupCount === 1 ? "" : "s"} — ${permit.farLoads} × (2 Near + 1 Far) and ${permit.groups.filter((group) => !group.far).length} × 4 Near.` : "No sandpit permit is needed because there are no sandpit orders."; return `<section class="page-title"><p class="eyebrow">STEP 3 — CAPACITY CHECK</p><h2>Demand against today’s fleet capability</h2><p>Near capacity is deliberately flexible: a truck can fill an unused Far or Stone slot with Near work when that is one of its capability plans.</p></section><section class="mini-summary ${dailyBalance < 0 ? "warning-summary" : ""}"><span><b>${activeOrders().reduce((sum, item) => sum + number(item.loads), 0)}</b> customer loads</span><span><b>${capacity.Daily}</b> fleet capacity</span><span><b>${dailyBalance >= 0 ? "+" : ""}${dailyBalance}</b> overall balance</span></section><section class="panel compact-panel permit-panel"><p class="eyebrow">SANDPIT PERMIT RECOMMENDATION</p><b>${esc(permitMessage)}</b><p>${permit.extraNearLoads ? `Add ${permit.extraNearLoads} Near sand load${permit.extraNearLoads === 1 ? "" : "s"} to complete the permit groups (${permit.nearLoads} now → ${permit.targetNearLoads} target).` : `Your ${permit.nearLoads} Near sand loads already fit the permit groups.`}</p><p>${permit.eligibleTruckCount >= permit.groupCount ? `${permit.eligibleTruckCount} trucks can cover the ${permit.groupCount} sandpit permits.` : `Only ${permit.eligibleTruckCount} suitable truck(s) can cover ${permit.groupCount} sandpit permits — adjust capability or availability.`}</p><p>After the sandpit plan, <b>${permit.suggestedQuarryOnlyCount}</b> of ${permit.workingTruckCount} working truck(s) can be Quarry Only. You marked <b>${permit.markedQuarryOnly}</b> Quarry Only today.</p>${quarryRotation ? `<p>Fair quarry rotation suggestion: <b>${esc(quarryRotation)}</b>.</p>` : ""}</section>${permitWarnings.length ? `<section class="alert"><b>Permit plan note</b>${permitWarnings.map((item) => `<p>${esc(item)}</p>`).join("")}</section>` : ""}<section class="panel compact-panel"><div class="table-scroll"><table class="compact-table capacity-table"><thead><tr><th>Trip type</th><th>Customer need</th><th>Possible maximum</th><th>Balance</th></tr></thead><tbody>${rows.map((row) => `<tr class="${row.capacity - row.need < 0 ? "mismatch" : "ok"}"><td>${row.zone}</td><td>${row.need}</td><td>${row.capacity}</td><td><b>${row.capacity - row.need >= 0 ? "+" : ""}${row.capacity - row.need}</b></td></tr>`).join("")}</tbody></table></div></section>${unresolved.length ? `<section class="alert"><b>Last dispatch could not place ${unresolved.length} load(s)</b>${unresolved.map((item) => `<p>${esc(customer(item.customerId)?.name || "Permit plan")} — ${esc(item.reason)}</p>`).join("")}</section>` : ""}<button class="primary wide" data-action="run-dispatch">Auto-generate dispatch</button><p class="workflow-next">Far and Stone loads are spread across different suitable trucks first whenever enough capable trucks are available. Own quarry orders are given to Quarry Only trucks first.</p>${activeAssignments().length ? tallyTable() : ""}`; }

function quarryEnquiryPickerLegacy() {
  const quarries = state.sources.filter((source) => source.type === "Quarry").sort((left, right) => left.name.localeCompare(right.name));
  const selected = new Set(quarryEnquiriesForDate(state, ui.date).map((source) => source.id));
  if (!quarries.length) return "";
  return `<section class="panel compact-panel quarry-enquiry-panel"><div class="section-head"><div><h2>Quarry enquiries for tomorrow</h2><small>Tick the quarries drivers may ask timbang for. The quarry name and contact will be added below Esok order batu in WhatsApp.</small></div></div><div class="quarry-enquiry-list">${quarries.map((source) => `<label class="quarry-enquiry-row"><input type="checkbox" data-quarry-enquiry-source="${esc(source.id)}" ${selected.has(source.id) ? "checked" : ""}><span><b>${esc(source.name)}</b><small>Timbang: ${esc(source.weighbridgeContact || "contact not set — add it in Settings")}${source.quarryNote ? ` · ${esc(source.quarryNote)}` : ""}</small></span></label>`).join("")}</div></section>`;
}
function financialPanel(finance) {
  const unconfigured = Math.max(0, finance.totalOrderLoads - finance.configuredOrderLoads);
  return `<section class="panel compact-panel finance-panel"><p class="eyebrow">ESTIMATED DAILY MARGIN</p><div class="finance-values"><span><small>Customer margin</small><b>${money(finance.customerMargin)}</b></span><span><small>Sandpit permits</small><b>${finance.permitCount} × ${money(state.settings?.sandpitPermitCost)}</b></span><span><small>Permit cost</small><b>− ${money(finance.permitCost)}</b></span><span><small>After permit cost</small><b class="${finance.netAfterPermit < 0 ? "negative" : ""}">${money(finance.netAfterPermit)}</b></span></div><small>${unconfigured ? `${unconfigured} customer load(s) do not have a margin entered yet, so they contribute RM 0.00 here.` : "Margin uses every current customer order. Add a customer’s margin per load and the permit cost in Settings."}</small></section>`;
}
function tallyPageV8() {
  const capacity = fleetTotals(); const demand = Object.fromEntries(orderTotals().map((item) => [item.zone, item.count])); const dailyBalance = capacity.Daily - activeOrders().reduce((sum, item) => sum + number(item.loads), 0);
  const rows = ["Near", "Far", "Stone"].map((zone) => ({ zone, need: demand[zone], capacity: capacity[zone] })); const unresolved = state.lastAllocation?.date === ui.date ? state.lastAllocation.unresolved || [] : []; const permitWarnings = state.lastAllocation?.date === ui.date ? state.lastAllocation.permitWarnings || [] : [];
  const permit = sandpitPermitPlan(state, ui.date); const finance = financialSummary(state, ui.date); const quarryRotation = permit.recommendedQuarryOnlyTruckIds.map((id) => truckLabel(truck(id))).join(" / "); const farGroups = permit.groups.filter((group) => group.far).length; const nearGroups = permit.groups.filter((group) => !group.far).length;
  const permitMessage = permit.groupCount ? `Full-capacity sandpit plan: ${farGroups ? `${farGroups} × (3 Near + 1 Far)` : ""}${farGroups && nearGroups ? " and " : ""}${nearGroups ? `${nearGroups} × 5 Near` : ""}.` : "No sandpit permit is needed because there are no sandpit orders.";
  const minimumMessage = permit.minimumExtraNearLoads ? `Find at least ${permit.minimumExtraNearLoads} more Near sand load${permit.minimumExtraNearLoads === 1 ? "" : "s"} so every planned permit has the minimum 3 sand loads.` : "Every planned permit can meet the minimum 3 sand loads.";
  const fullMessage = permit.fullCapacityExtraNearLoads ? `For full permit use, find ${permit.fullCapacityExtraNearLoads} more Near sand load${permit.fullCapacityExtraNearLoads === 1 ? "" : "s"} (${permit.nearLoads} now → ${permit.targetNearLoads} full-capacity target).` : "Your current Near sand loads already fill the high-capacity permit plan.";
  return `<section class="page-title"><p class="eyebrow">STEP 3 — CAPACITY CHECK</p><h2>Demand, permits and quarry rotation</h2><p>Use this as a guide, then decide the exact routes yourself on the truck board.</p></section><section class="mini-summary ${dailyBalance < 0 ? "warning-summary" : ""}"><span><b>${activeOrders().reduce((sum, item) => sum + number(item.loads), 0)}</b> customer loads</span><span><b>${capacity.Daily}</b> fleet capacity</span><span><b>${dailyBalance >= 0 ? "+" : ""}${dailyBalance}</b> overall balance</span></section><section class="panel compact-panel permit-panel"><p class="eyebrow">SANDPIT PERMIT RECOMMENDATION</p><b>${esc(permitMessage)}</b><p><b>Permit minimum:</b> ${esc(minimumMessage)}</p><p><b>Maximum use:</b> ${esc(fullMessage)}</p><p>${permit.eligibleTruckCount >= permit.groupCount ? `${permit.eligibleTruckCount} truck(s) can cover the ${permit.groupCount} sandpit permit(s).` : `Only ${permit.eligibleTruckCount} suitable truck(s) can cover ${permit.groupCount} sandpit permit(s) — adjust capability or availability.`}</p><p>After the sandpit plan, <b>${permit.suggestedQuarryOnlyCount}</b> of ${permit.workingTruckCount} working truck(s) can be Quarry Only. You marked <b>${permit.markedQuarryOnly}</b> Quarry Only today.</p>${quarryRotation ? `<p>Fair quarry rotation suggestion: <b>${esc(quarryRotation)}</b>.</p>` : ""}</section>${financialPanel(finance)}${quarryEnquiryPicker()}${permitWarnings.length ? `<section class="alert"><b>Permit plan note</b>${permitWarnings.map((item) => `<p>${esc(item)}</p>`).join("")}</section>` : ""}<section class="panel compact-panel"><div class="table-scroll"><table class="compact-table capacity-table"><thead><tr><th>Trip type</th><th>Customer need</th><th>Possible maximum</th><th>Balance</th></tr></thead><tbody>${rows.map((row) => `<tr class="${row.capacity - row.need < 0 ? "mismatch" : "ok"}"><td>${row.zone}</td><td>${row.need}</td><td>${row.capacity}</td><td><b>${row.capacity - row.need >= 0 ? "+" : ""}${row.capacity - row.need}</b></td></tr>`).join("")}</tbody></table></div></section>${unresolved.length ? `<section class="alert"><b>Last saved dispatch could not place ${unresolved.length} load(s)</b>${unresolved.map((item) => `<p>${esc(customer(item.customerId)?.name || "Permit plan")} — ${esc(item.reason)}</p>`).join("")}</section>` : ""}<button class="primary wide" data-tab="dispatch">Open truck-first dispatch board</button><p class="workflow-next">Place the exact customer loads yourself, based on the delivery timeline, each driver's capacity and the fairness reminder.</p>${activeAssignments().length ? tallyTable() : ""}`;
}
function quarryLogCellLegacy(item, trips) { if (trips.length || !isDispatchable(item)) return "<td class='grid-empty'>—</td>"; const log = (state.quarryTripLogs || []).find((entry) => entry.date === ui.date && entry.truckId === item.id); const open = log || ui.openQuarryLogTruck === item.id; if (!open) return `<td class="quarry-log-cell quarry-log-add"><b>No company order</b><button class="tiny-add" data-action="add-quarry-log" data-truck="${esc(item.id)}">+ Add quarry order</button></td>`; return `<td class="quarry-log-cell" data-quarry-truck="${esc(item.id)}"><b>Quarry order done</b><label>Loads<input type="number" min="0" inputmode="numeric" data-quarry-field="loads" value="${esc(number(log?.loads))}"></label><input data-quarry-field="remark" value="${esc(log?.remark || "")}" placeholder="Which quarry / order note"></td>`; }
function gridRows(type) { const columns = tripColumns(); return state.trucks.filter((item) => !["off", "breakdown"].includes(String(item.status).toLowerCase())).map((item) => { const trips = activeAssignments().filter((assignment) => assignment.truckId === item.id).sort((a, b) => a.tripNumber - b.tripNumber); return `<tr data-truck="${esc(item.id)}" data-status="${esc(item.status.toLowerCase())}"><td class="sticky-col grid-truck"><b class="truck-name">${esc(truckLabel(item))}</b>${badge(item.status)}<small>${trips.length}/${maximumTruckTrips(item)} own orders</small></td>${Array.from({ length: columns }, (_, index) => type === "dispatch" ? dispatchCell(trips[index]) : logCell(trips[index])).join("")}${type === "log" ? quarryLogCell(item, trips) : ""}</tr>`; }).join(""); }
function dispatchCell(assignment) { if (!assignment) return "<td class='grid-empty'>—</td>"; return `<td class="dispatch-grid-cell"><b>${esc(customer(assignment.customerId)?.name || "Unknown customer")}</b><small>${esc(assignment.zone)}${assignment.early ? " · Early" : ""}</small><button class="delete" data-action="remove-trip" data-id="${esc(assignment.id)}" aria-label="Remove this trip">×</button></td>`; }
function shortDispatchDate(value) { try { return new Intl.DateTimeFormat("en-MY", { day: "numeric", month: "short" }).format(new Date(`${value}T12:00:00`)); } catch { return value; } }
function dispatchOrders() { return activeOrders().filter((item) => number(item.loads) > 0); }
function deliveryWindowOptions(selected = "") { const values = ["", "Before 10:00 am", "Before 12:00 pm", "After 2:00 pm", "After 4:00 pm", "Any time"]; const options = values.includes(selected) ? values : [...values, selected]; return options.map((value) => `<option value="${esc(value)}" ${value === selected ? "selected" : ""}>${esc(value || "Any time")}</option>`).join(""); }
function dispatchOrderLabel(order) { return `${customer(order.customerId)?.name || "Unknown customer"} · ${materialLabel(state, order.materialId)}${order.early ? " · Early" : ""}${order.deliveryWindow ? ` · ${order.deliveryWindow}` : ""}`; }
function dispatchOrderOptionsLegacy(targetTruck, selectedOrderId = "", assignment = null) {
  const available = dispatchOrders().filter((order) => order.id === selectedOrderId || dailyPlanAllowsOrder(targetTruck.id, order.id, assignment?.id)); const found = available.some((item) => item.id === selectedOrderId);
  const legacy = assignment && !found ? `<option value="${esc(selectedOrderId)}" selected>${esc(customer(assignment.customerId)?.name || "Previous order")} · keep or replace</option>` : "";
  return `<option value="">— Empty slot —</option>${legacy}${available.slice().sort((left, right) => dispatchOrderLabel(left).localeCompare(dispatchOrderLabel(right))).map((order) => { const planned = activeAssignments().filter((item) => item.orderId === order.id && item.status !== "Skipped").length; return `<option value="${esc(order.id)}" ${order.id === selectedOrderId ? "selected" : ""}>${esc(dispatchOrderLabel(order))} (${planned}/${number(order.loads)})</option>`; }).join("")}`;
}
function dispatchSlotCellLegacy(targetTruck, assignment, slot) {
  if (!isDispatchable(targetTruck)) return assignment
    ? `<td class="truck-slot inactive-slot"><b>${esc(customer(assignment.customerId)?.name || "Unknown customer")}</b><small>${esc(targetTruck.status)} — set this truck available before changing the route</small></td>`
    : `<td class="truck-slot inactive-slot"><small>${esc(targetTruck.status)} — no dispatch</small></td>`;
  if (assignment && assignment.status !== "Planned") return `<td class="truck-slot completed-slot"><b>${esc(customer(assignment.customerId)?.name || "Unknown customer")}</b><small>${esc(assignment.status)} — update in Trip log</small></td>`;
  if (assignment) return `<td class="truck-slot"><select data-dispatch-slot-assignment="${esc(assignment.id)}" aria-label="${esc(truckLabel(targetTruck))} trip ${slot}">${dispatchOrderOptions(targetTruck, assignment.orderId, assignment)}</select><button class="delete slot-clear" data-action="remove-trip" data-id="${esc(assignment.id)}" aria-label="Clear trip ${slot}">×</button></td>`;
  return `<td class="truck-slot empty-slot"><select data-dispatch-slot-truck="${esc(targetTruck.id)}" aria-label="${esc(truckLabel(targetTruck))} trip ${slot}">${dispatchOrderOptions(targetTruck)}</select></td>`;
}
function truckFirstRowLegacy(item, columns) {
  const trips = activeAssignments().filter((assignment) => assignment.truckId === item.id).sort((left, right) => left.tripNumber - right.tripNumber); const plan = dailyFleetPlan(item); const capacity = planTotal(plan); const planned = trips.length; const left = Math.max(0, capacity - planned); const check = !dailyPlanFits(item, plan) ? "Check plan" : planned > capacity ? "Over" : planned === capacity ? "Full" : `${left} left`;
  return `<tr data-dispatch-status="${esc(String(item.status).toLowerCase())}"><td class="sticky-col dispatch-truck"><b class="truck-name">${esc(truckLabel(item))}</b><small>${esc(dailyPlanSummary(plan))} · ${capacity} loads</small></td>${Array.from({ length: columns }, (_, index) => index < capacity ? dispatchSlotCell(item, trips[index], index + 1) : "<td class='not-planned-slot'>—</td>").join("")}<td class="planned-cell"><b>${planned}</b></td><td class="remaining-cell"><b>${left}</b></td><td class="capacity-check ${(!dailyPlanFits(item, plan) || planned > capacity) ? "over" : ""}">${esc(check)}</td></tr>`;
}
function fairnessHistoryPanel() {
  const options = [...new Map(dispatchOrders().map((item) => [item.customerId, customer(item.customerId)])).values()].filter(Boolean); const selected = customer(ui.historyCustomer) || options[0]; if (!selected) return "";
  const history = customerDeliveryHistory(state, { customerId: selected.id, beforeDate: ui.date, limit: 10, deliveryDays: 0 });
  const fullHistory = customerDeliveryHistory(state, { customerId: selected.id, beforeDate: ui.date, limit: 10000, deliveryDays: 0 });
  const latestByTruck = new Map(); fullHistory.recent.forEach((entry) => { if (!latestByTruck.has(entry.truckId)) latestByTruck.set(entry.truckId, entry.date); });
  const suggestionTrucks = dispatchableTrucks().slice().sort((left, right) => { const leftDate = latestByTruck.get(left.id) || ""; const rightDate = latestByTruck.get(right.id) || ""; return leftDate.localeCompare(rightDate) || number(left.sequence) - number(right.sequence) || truckLabel(left).localeCompare(truckLabel(right)); }).slice(0, 3);
  const exceptions = (state.tripLogs || []).filter((log) => log.date < ui.date && log.plannedCustomerId === selected.id && ["Changed", "Skipped"].includes(log.status)).sort((left, right) => right.date.localeCompare(left.date) || String(right.updatedAt || right.recordedAt).localeCompare(String(left.updatedAt || left.recordedAt))).slice(0, 10);
  const deliveries = history.recent.map((entry) => `<div class="delivery-history-row"><b>${esc(shortDispatchDate(entry.date))}</b><span>${esc(truckLabel(truck(entry.truckId)))}</span></div>`).join("") || "<small class='delivery-history-none'>No completed actual trip yet.</small>";
  const changes = exceptions.length ? `<div class="history-exceptions"><b>Changed / skipped planned trips</b>${exceptions.map((log) => { const actual = customer(log.actualCustomerId)?.name || "no delivery"; const note = log.remark || (log.status === "Changed" ? `Actual: ${actual}` : "No remark"); return `<div class="history-exception-row"><b>${esc(shortDispatchDate(log.date))} · ${esc(truckLabel(truck(log.truckId)))} · ${esc(log.status)}</b><small>${esc(note)}</small></div>`; }).join("")}</div>` : "";
  const suggestions = suggestionTrucks.length ? `<div class="history-suggestions"><b>Suggested next 3</b><small>Working trucks that have gone longest without this delivery.</small><div>${suggestionTrucks.map((item) => `<span><b>${esc(truckLabel(item))}</b><small>${latestByTruck.get(item.id) ? `Last ${esc(shortDispatchDate(latestByTruck.get(item.id)))}` : "No recorded trip"}</small></span>`).join("")}</div></div>` : "";
  return `<section class="panel compact-panel fairness-panel"><div class="section-head"><div><p class="eyebrow">FAIRNESS REMINDER</p><h2>Actual delivery history</h2></div></div><label class="history-customer-picker">Customer<select data-history-customer>${options.map((item) => `<option value="${esc(item.id)}" ${item.id === selected.id ? "selected" : ""}>${esc(item.name)}</option>`).join("")}</select></label>${suggestions}<div class="delivery-history-list"><small>Latest 10 completed deliveries</small>${deliveries}</div>${changes}</section>`;
}
function actualLogFor(assignment) { return state.tripLogs.find((item) => item.assignmentId === assignment?.id); }
function effectiveOrderTally() {
  const orders = dispatchOrders(); const rows = new Map(orders.map((order) => [order.id, { order, onBoard: 0, actual: 0 }])); const unmatched = [];
  const chooseOrder = ({ customerId, materialId, zone, fallbackOrderId = "" }) => {
    if (fallbackOrderId && rows.has(fallbackOrderId)) return rows.get(fallbackOrderId);
    const candidates = orders.filter((order) => order.customerId === customerId).sort((left, right) => {
      const score = (order) => (order.materialId === materialId ? 0 : 4) + (order.zone === zone ? 0 : 1);
      return score(left) - score(right) || number(left.sequence) - number(right.sequence);
    });
    return candidates.map((order) => rows.get(order.id)).find((row) => row.onBoard < number(row.order.loads)) || candidates.map((order) => rows.get(order.id))[0];
  };
  activeAssignments().forEach((assignment) => {
    if (assignment.status === "Skipped" || assignment.quarryRequestId || !assignment.customerId) return;
    const log = actualLogFor(assignment); const actualCustomerId = log?.actualCustomerId || assignment.customerId; const actualMaterialId = log?.actualMaterialId || assignment.materialId;
    const unchanged = !log || (actualCustomerId === assignment.customerId && actualMaterialId === assignment.materialId);
    const row = chooseOrder({ customerId: actualCustomerId, materialId: actualMaterialId, zone: assignment.zone, fallbackOrderId: unchanged ? assignment.orderId : "" });
    if (!row) { if (log?.status === "Changed") unmatched.push(customer(actualCustomerId)?.name || "Unknown customer"); return; }
    row.onBoard += 1;
    if (["Completed", "Changed"].includes(log?.status || assignment.status)) row.actual += 1;
  });
  (state.extraTripLogs || []).filter((entry) => entry.date === ui.date).forEach((entry) => {
    const row = chooseOrder({ customerId: entry.customerId, materialId: entry.materialId, zone: customer(entry.customerId)?.defaultZone || "Near" });
    if (!row) { unmatched.push(customer(entry.customerId)?.name || "Unknown customer"); return; }
    row.onBoard += number(entry.loads) || 1; row.actual += number(entry.loads) || 1;
  });
  return { rows: [...rows.values()], unmatched: [...new Set(unmatched)] };
}
function orderTallyTable() {
  const tally = effectiveOrderTally(); const allTally = tally.rows.every((row) => row.onBoard === number(row.order.loads));
  return `<section class="panel compact-panel tally-panel"><div class="section-head"><div><h2>Order tally</h2><small>Changed and completed trips update this table using the actual customer and material in Trip log.</small></div><span>${allTally ? badge("Tally") : badge("Review")}</span></div><div class="table-scroll tally-short-scroll" data-scroll-key="order-tally"><table class="compact-table order-tally-table"><thead><tr><th>Customer</th><th>Need</th><th>On board</th><th>Done</th><th>Left</th></tr></thead><tbody>${tally.rows.map(({ order, onBoard, actual }) => { const balance = onBoard - number(order.loads); return `<tr class="${balance === 0 ? "ok" : "mismatch"}"><td><b>${esc(customer(order.customerId)?.name || "Unknown customer")}</b><small>${esc(shortMaterialLabel(order.materialId))} · ${esc(order.zone)}${order.early ? " · Early" : ""}</small></td><td>${number(order.loads)}</td><td>${onBoard}</td><td>${actual}</td><td><b>${balance > 0 ? "+" : ""}${balance}</b></td></tr>`; }).join("") || "<tr><td colspan='5' class='empty-cell'>No order lines to check.</td></tr>"}</tbody></table></div>${tally.unmatched.length ? `<div class="alert"><b>Actual delivery not in tomorrow's order</b><p>${esc(tally.unmatched.join(", "))} - add its order line if it should be counted in the tally.</p></div>` : ""}</section>`;
}
function dispatchPageLegacy() {
  const orders = dispatchOrders(); const planned = activeAssignments().length; const required = orders.reduce((sum, item) => sum + number(item.loads), 0); const boardTrucks = dispatchableTrucks().filter((item) => planTotal(dailyFleetPlan(item)) || activeAssignments().some((assignment) => assignment.truckId === item.id)); const columns = Math.max(1, ...boardTrucks.map((item) => Math.max(planTotal(dailyFleetPlan(item)), activeAssignments().filter((assignment) => assignment.truckId === item.id).length))); const working = boardTrucks.length;
  if (!orders.length) return `<section class="page-title"><p class="eyebrow">STEP 4 — TRUCK-FIRST DISPATCH</p><h2>Plan from your fleet</h2><p>Enter tomorrow’s customer orders first. Then this board will let you place each delivery into a truck trip slot.</p></section><div class="empty"><b>No customer orders for this date.</b><p>Add your orders, then come back to fill the truck board.</p><button class="primary" data-tab="orders">Go to orders</button></div>`;
  return `<section class="page-title"><p class="eyebrow">STEP 4 — TRUCK-FIRST DISPATCH</p><h2>Build the route one truck at a time</h2><p>Set each truck’s Near, Far and Stone capacity first. Only working trucks with a daily capacity appear here.</p></section><section class="mini-summary ${planned === required ? "" : "warning-summary"}"><span><b>${working}</b> trucks on board</span><span><b>${required}</b> customer loads</span><span><b>${planned}</b> placed</span><span><b>${planned - required >= 0 ? "+" : ""}${planned - required}</b> overall balance</span></section>${fairnessHistoryPanel()}${boardTrucks.length ? `<section class="panel compact-panel truck-first-panel"><div class="section-head"><div><h2>Tomorrow’s truck board</h2><small>Only the capacity you set appears as editable yellow slots.</small></div></div><div class="table-scroll truck-first-scroll"><table class="compact-table truck-first-table"><thead><tr><th class="sticky-col">Truck</th>${Array.from({ length: columns }, (_, index) => `<th class="trip-head">Trip ${index + 1}${index === 0 ? "<br>Early" : ""}</th>`).join("")}<th class="summary-head">Plan</th><th class="summary-head">Left</th><th class="summary-head">Check</th></tr></thead><tbody>${boardTrucks.map((item) => truckFirstRow(item, columns)).join("")}</tbody></table></div></section>` : `<div class="empty"><b>No truck capacity is set yet.</b><p>Go to Trucks and enter Near, Far or Stone loads for at least one available truck.</p><button class="primary" data-tab="trucks">Open tomorrow’s fleet</button></div>`}${orderTallyTable()}`;
}

function actualMaterialOptions(customerId, selected = "") { const target = customer(customerId); const ids = target ? customerAllowedMaterialIds(state, target) : []; const picked = ids.includes(selected) ? selected : (ids.includes(defaultCustomerMaterialId(state, target)) ? defaultCustomerMaterialId(state, target) : ids[0]); return ids.length ? ids.map((id) => `<option value="${esc(id)}" ${id === picked ? "selected" : ""}>${esc(materialLabel(state, id))}</option>`).join("") : "<option value=\"\">No saved material for this customer</option>"; }
function logCell(assignment) { if (!assignment) return "<td class='grid-empty'>—</td>"; const log = state.tripLogs.find((item) => item.assignmentId === assignment.id); const status = log?.status || "Planned"; const actual = log?.actualCustomerId || assignment.customerId; const actualMaterialId = log?.actualMaterialId || (actual === assignment.customerId ? assignment.materialId : defaultCustomerMaterialId(state, customer(actual))); return `<td class="log-grid-cell" data-log-assignment="${esc(assignment.id)}" data-log-status="${esc(status)}"><b>${esc(customer(assignment.customerId)?.name || "Unknown customer")}</b><select data-log-field="status"><option ${status === "Planned" ? "selected" : ""}>Planned</option><option ${status === "Completed" ? "selected" : ""}>Completed</option><option ${status === "Changed" ? "selected" : ""}>Changed</option><option ${status === "Skipped" ? "selected" : ""}>Skipped</option></select><div class="actual-trip-fields"><label>Actual customer<select data-log-field="actualCustomerId">${customerOptions(actual)}</select></label><label>Actual material<select data-log-field="actualMaterialId">${actualMaterialOptions(actual, actualMaterialId)}</select></label></div><input data-log-field="remark" value="${esc(log?.remark || "")}" placeholder="Remark">${log ? `<button class="tiny-reset" data-action="clear-log" data-id="${esc(assignment.id)}">Reset</button>` : ""}</td>`; }
function logsPage() { const columns = tripColumns(); const visible = state.trucks.some((item) => !["off", "breakdown"].includes(String(item.status).toLowerCase())); return `<section class="page-title"><p class="eyebrow">STEP 6 — ACTUAL TRIPS</p><h2>Trip log board</h2><p>Choose Changed to reveal the actual customer field. If a working truck has no own order, enter its quarry-order loads in the final column.</p></section>${visible ? `<section class="panel compact-panel"><div class="table-scroll grid-scroll"><table class="compact-table log-grid"><thead><tr><th class="sticky-col">Truck</th>${Array.from({ length: columns }, (_, index) => `<th>Trip ${index + 1}</th>`).join("")}<th>Quarry order log</th></tr></thead><tbody>${gridRows("log")}</tbody></table></div></section>` : `<div class="empty"><b>No working truck today.</b><p>Set a truck to Available, Scheduled Repair, or Quarry Only first.</p></div>`}`; }
