  if (action === "mark-driver-absent") { state = markDriverAbsent(state, { date: ui.date, truckId: button.dataset.truck }); persistAndRender("Driver absent — remaining planned trips skipped"); return; }
  if (action === "clear-driver-absent") { state = clearDriverAbsent(state, { date: ui.date, truckId: button.dataset.truck }); persistAndRender("Driver absence undone"); return; }
