  if (action === "add-quarry-trip-log") { const next = addQuarryTripLog(state, { date: ui.date, truckId: button.dataset.truck }); if (next === state) return showToast("Add a quarry and its products in Settings first", "danger"); state = next; persistAndRender("Quarry trip row added"); return; }
  if (action === "remove-quarry-log") { state = removeQuarryTripLog(state, button.dataset.id); persistAndRender("Quarry trip removed"); return; }
  if (action === "set-dispatch-date") { ui.date = button.dataset.date; const copied = prepareDate(ui.date); renderKeepingView(); if (copied) flashSave("Previous plan copied"); return; }
  if (action === "move-sequenced") { if (moveSequencedList(button.dataset.list, button.dataset.id, button.dataset.direction)) persistAndRender("Message order updated"); return; }
  if (action === "delete-quarry-request") { state = { ...state, quarryRequests: (state.quarryRequests || []).filter((item) => item.id !== button.dataset.id), assignments: state.assignments.filter((item) => item.quarryRequestId !== button.dataset.id) }; persistAndRender("Quarry truck request removed"); return; }
  if (action === "apply-orientation") return applyScreenOrientation();
