  if (action === "step-value") { const input = button.parentElement.querySelector("input"); const next = number(number(input.value) + Number(button.dataset.delta)); if (button.dataset.entity === "order") updateOrder(button.dataset.id, button.dataset.field, next); if (button.dataset.entity === "capability") updateCapability(button.dataset.id, button.dataset.field, next); if (button.dataset.entity === "repair") updateRepair(button.dataset.id, button.dataset.field, next); if (button.dataset.entity === "dailyplan") updateDailyFleetPlan(button.dataset.id, button.dataset.field, next); if (button.dataset.entity === "quarrylog") state = updateQuarryTripLog(state, button.dataset.id, button.dataset.field, next); if (button.dataset.entity === "extralog") state = updateExtraTripLog(state, button.dataset.id, button.dataset.field, Math.max(1, next)); if (button.dataset.entity === "quarryrequest") updateQuarryRequest(button.dataset.id, button.dataset.field, Math.max(1, next)); input.value = next; autosave(); if (button.dataset.entity === "dailyplan") refreshDailyFleetUi(button.dataset.id); return; }
