  if (action === "assign-order-load") { const truckId = button.parentElement.querySelector("[data-manual-truck]")?.value; const order = state.orders.find((item) => item.id === button.dataset.order && item.date === ui.date); if (!order || !truckId) return showToast("Choose a working truck first", "danger"); const scoped = stateForDate(); const next = addManualOrderLoad(scoped, { date: ui.date, orderId: order.id, truckId }); if (next === scoped) return showToast("That truck is not available today", "danger"); state = mergeDateAwareSchedulerResult(next); persistAndRender(`${truckLabel(truck(truckId))} added to ${customer(order.customerId)?.name || "this customer"}`); return; }
