  if (element.dataset.dispatchSlotAssignment !== undefined) { const assignment = state.assignments.find((item) => item.id === element.dataset.dispatchSlotAssignment); if (!assignment) return; if (!element.value) { state = { ...state, assignments: state.assignments.filter((item) => item.id !== assignment.id) }; persistAndRender("Trip slot cleared"); return; } const quarryRequestId = element.value.startsWith("quarry-request:") ? element.value.slice("quarry-request:".length) : ""; const scoped = stateForDate(); if (quarryRequestId) { if (!dailyPlanAllowsQuarryRequest(assignment.truckId, assignment.id)) return showToast("This quarry request is outside the total truck capacity", "danger"); const next = replaceManualAssignmentQuarryRequest(scoped, { assignmentId: assignment.id, requestId: quarryRequestId }); if (next === scoped) return showToast("Completed trips can only be changed in Trip log", "danger"); state = mergeDateAwareSchedulerResult(next); persistAndRender("Trip changed to quarry request"); return; } if (!dailyPlanAllowsOrder(assignment.truckId, element.value, assignment.id)) return showToast("This order is outside the Near / Far / Stone capacity set for this truck", "danger"); const next = replaceManualAssignmentOrder(scoped, { assignmentId: assignment.id, orderId: element.value }); if (next === scoped) return showToast("Completed trips can only be changed in Trip log", "danger"); state = mergeDateAwareSchedulerResult(next); persistAndRender("Trip order changed"); return; }
  if (element.dataset.truckField) { const row = element.closest("[data-truck],[data-daily-truck]"); const truckId = row?.dataset.truck || row?.dataset.dailyTruck; if (!truckId) return; updateTruck(truckId, element.dataset.truckField, element.value); if (element.dataset.truckField === "status") { persistAndRender("Truck status updated"); return; } autosave(); if (row.dataset.dailyTruck) refreshDailyFleetUi(truckId); return; }
  if (element.dataset.dailyplanField) { const row = element.closest("[data-daily-truck]"); if (!row) return; updateDailyFleetPlan(row.dataset.dailyTruck, element.dataset.dailyplanField, element.value); autosave(); refreshDailyFleetUi(row.dataset.dailyTruck); return; }
  if (element.dataset.repairField) { updateRepair(element.closest("[data-truck]").dataset.truck, element.dataset.repairField, element.type === "checkbox" ? element.checked : element.value); autosave(); return; }
