  if (element.dataset.ruleSourceId !== undefined) { const editor = element.closest("[data-customer]"); const ruleId = element.closest("[data-rule]").dataset.rule; const current = customer(editor.dataset.customer)?.materialRules?.find((rule) => rule.id === ruleId)?.sourceIds || []; const sourceIds = element.checked ? [...new Set([...current, element.dataset.ruleSourceId])] : current.filter((id) => id !== element.dataset.ruleSourceId); updateCustomerRule(editor.dataset.customer, ruleId, "sourceIds", sourceIds); autosave("Customer sources saved"); return; }
  if (element.dataset.ruleSources !== undefined) { const editor = element.closest("[data-customer]"); updateCustomerRule(editor.dataset.customer, element.closest("[data-rule]").dataset.rule, "sourceIds", [...element.selectedOptions].map((option) => option.value)); autosave(); return; }
